        for (int j = 0; j < k; j++) cin >> target[i][j];
    }

    // BFS over states
    map<vector<vector<int>>, int> dist;
    queue<vector<vector<int>>> q;

    dist[initial] = 0;
    q.push(initial);

    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        int d = dist[cur];

        if (cur == target) {
            cout << d << endl;
            return 0;
        }

        // Try all moves: move suffix of track i to track j
        for (int i = 0; i < n; i++) {
            if (cur[i].empty()) continue;
            for (int len = 1; len <= (int)cur[i].size(); len++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    auto next = cur;
                    // Move last 'len' cars from track i to track j
                    vector<int> moved(next[i].end() - len, next[i].end());
                    next[i].resize(next[i].size() - len);
                    for (int x : moved) next[j].push_back(x);

                    if (!dist.count(next)) {
                        dist[next] = d + 1;
                        q.push(next);
                    }
                }
            }
        }
    }

    cout << -1 << endl;
    return 0;
