        // Build graph for exchange lines
        int[][] dist = new int[N][N];
        for (int i = 0; i < N; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
        }
        for (int i = 0; i < M; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            dist[u][v] = 1;
            dist[v][u] = 1;
        }

        // Floyd-Warshall for shortest paths
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (dist[i][k] + dist[k][j] < dist[i][j]) {
                        dist[i][j] = dist[i][k] + dist[k][j];
                    }
                }
            }
        }

        // For each line, find longest matching suffix
        int totalMoves = 0;
        for (int i = 0; i < N; i++) {
            List<Integer> initLine = initial.get(i);
            List<Integer> tgtLine = target.get(i);

            int p = initLine.size() - 1;
            int q = tgtLine.size() - 1;
            while (p >= 0 && q >= 0 && initLine.get(p).equals(tgtLine.get(q))) {
                p--;
                q--;
            }
            // Cars from index 0 to p (inclusive) need to be moved away
            int carsToMove = p + 1;
            if (carsToMove > 0) {
                // We need at least one move to shift them elsewhere
                // Find nearest line j that is reachable
                int minDist = INF;
                for (int j = 0; j < N; j++) {
                    if (j != i && dist[i][j] < minDist) {
                        minDist = dist[i][j];
                    }
